SourceCode.Declaration:
/// <summary>
/// This class is used to automatically finalize the final leg transfer orders when the source leg transfer orders are shipped
/// </summary>
public class METCrossDockTransferFinalizationFacade
{
}

Method.Source:
/// <summary>
/// Starting point for transfer order finalization process. 
/// </summary>
/// <param name = "_transferTable">Transfer order table buffer to be finalized</param>
public void process(InventTransferTable _transferTable)
{
    container ocsCodeCon, transferOrderOSCCon;
    METOSCCode oscCode;

    METInventTransferTableExt transferTableExt = METInventTransferTableExt::findByTransferId(_transferTable.TransferId);
    MetShipmentId shipmentId = this.createUpdateShipment(_transferTable.TransferId);

    METTransferPickingListGenerationTaskContract contract = new METTransferPickingListGenerationTaskContract();
    contract.parmSkipFinalisationProcess(this.skipFinalize(_transferTable));
    contract.parmTransferId(_transferTable.TransferId);
    contract.parmShipmentIdList([shipmentId]);

    try
    {
        METTransferPickingListGenerationTaskService pickTaskService = new METTransferPickingListGenerationTaskService();
        pickTaskService.setExtractFinalLegTO(true);
        pickTaskService.process(contract);

        this.registerPickList(_transferTable);
    }
    catch
    {
        Info("@Budget:UpdateCancelled");
    }
}

private void registerPickList(InventTransferTable _transferTable)
{
    container conOrdTrans;
    WMSOrderTrans orderTrans;

    select firstonly orderTrans where orderTrans.inventTransRefId == _transferTable.TransferId;

    conOrdTrans = [orderTrans.RecId];

    SysOperationServiceController controller      = new SysOperationServiceController(
                                            classStr(METPickingListRegistrationPostingJob),
                                            methodStr(METPickingListRegistrationPostingJob, postPickListRegistration));

    controller.parmDialogCaption(strFmt("@MET:PostPackingSlipSubTask", 1));
    controller.parmShowDialog(false);
    METDallasPicklistRegContract metDataContract = controller.getDataContractObject() as METDallasPicklistRegContract;
    metDataContract.parmConOrderTrans(conOrdTrans);
    controller.startOperation();
}

/// <summary>
/// Creates and updates 
/// </summary>
/// <param name = "_transferId"></param>
/// <returns></returns>
private MetShipmentId createUpdateShipment(InventTransferId _transferId)
{
    //TransferPickingListGenerationTaskController.startOperation();
    //Create shipment header and loads to prevent the batch task dead lock issue.
    METOrderShipmentLoadCreation metOrderShipmentloadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::TransferOrder, _transferId);
    MetShipmentId metShipmentId = metOrderShipmentloadCreation.createShippmentLoad(true, true);

    return metShipmentID;
}

private boolean skipFinalize(InventTransferTable _transferTable)
{
    boolean ret = false;

    METInventTransferLine metTransLine;
    InventTransferLine transLine;
    InventTransferTable transTable;

     select firstonly TransferOrderNumber from metTransLine
        group by TransferOrderNumber
        exists join transLine
        where transLine.RecId == metTransLine.InventTransferLine
        && transLine.TransferId == _transferTable.TransferId
        exists join transTable
        where transTable.TransferId == metTransLine.TransferOrderNumber
        && transTable.TransferStatus == InventTransferStatus::Created;

    ret = metTransLine.TransferOrderNumber == '' ? false : true;

    return ret;
}
